mapper.select:
select a.id, a.name, b.name as customer, d.name as supplier, a.owner_user, a.bus_status, a.deal_time,
       a.contact_status, a.settle_status,a.contact_amount, a.credit_amount, a.remark, a.fail_remark,
       e.user_name as creator, c.user_name as updater, a.create_time, a.update_time, a.deleted
       from crm_business a
       left join crm_customer b on a.customer_id=b.id
       left join sys_user c on a.updater=c.user_id
       left join crm_supplier d on a.supplier_id=d.id
       left join sys_user e on a.creator=e.user_id

    a.deleted =0
     and a.name like concat('%', #{name}, '%')
     and a.customer_id = #{customerId}
     and a.supplier_id = #{supplierId}
     and a.owner_user = #{ownerUser}
     and a.bus_status = #{busStatus}
     and a.deal_time = #{dealTime}
     and a.contact_status = #{contactStatus}
     and a.settle_status = #{settleStatus}
     and a.contact_amount = #{contactAmount}
     and a.credit_amount = #{creditAmount}
     and a.fail_remark = #{failRemark}
     and a.creator = #{creator}
     and a.updater = #{updater}

mapper.update:
update crm_business
name = #{name}, customer_id = #{customerId}, supplier_id = #{supplierId}, owner_user = #{ownerUser}, bus_status = #{busStatus}, deal_time = #{dealTime}, contact_status = #{contactStatus}, settle_status = #{settleStatus}, contact_amount = #{contactAmount}, credit_amount = #{creditAmount}, remark = #{remark}, fail_remark = #{failRemark}, creator = #{creator}, updater = #{updater}, create_time = #{createTime}, update_time = #{updateTime}, deleted = #{deleted},
where id = #{id}
